#!/usr/bin/env python3
"""Import sanitized scout balcony geometry; never copy reservation/database IDs."""
import argparse, collections, hashlib, json, pathlib, re, xml.etree.ElementTree as E
p=argparse.ArgumentParser(description=__doc__);p.add_argument('snapshot',type=pathlib.Path);a=p.parse_args()
x=json.loads(a.snapshot.read_text());assert x['configuration']['dimensions']=={'width':28,'height':52}
seats=sorted([[s['table'],s['label'],s['x'],s['y']] for s in x['seats']])
assert len(seats)==249 and len({s[1] for s in seats})==249
assert collections.Counter(s[0] for s in seats)=={i:10 if i<=15 else 14 if i<=21 else 15 for i in range(1,23)}
paths=[n for n in E.fromstring(x['background_svg']).iter() if n.tag.endswith('}path')]
numbers=[1,2,7,3,6,5,4,8,10,11,12,15,14,13,16,17,18,19,20,21,9]
assert len(paths)==len(numbers)
tables=[]
for number,n in zip(numbers,paths):
 pairs=re.findall(r'([-\d.]+)[ ,]+([-\d.]+)',n.attrib['d']);xx=[float(v[0])*2800/3653 for v in pairs];yy=[float(v[1])*5200/6761 for v in pairs]
 tables.append([number,min(xx),min(yy),max(xx),max(yy)])
tables.sort();data={'tables':tables,'seats':seats};digest=hashlib.sha256(json.dumps(data,sort_keys=True).encode()).hexdigest()
lines=['// Generated by tool/import_scout_balcony_reference.py; structure only.',f"const scoutBalconyReferenceDigest = '{digest}';"]
for name,rows in data.items():
 typ='(int, String, int, int)' if name=='seats' else '(int, double, double, double, double)'
 lines.append(f'const scoutBalcony{name.title()} = <{typ}>[')
 for row in rows: lines.append('  ('+', '.join(json.dumps(v,ensure_ascii=False) if isinstance(v,str) else str(round(v,6)) if isinstance(v,float) else str(v) for v in row)+'),')
 lines.append('];')
root=pathlib.Path(__file__).resolve().parents[1];(root/'lib/src/templates/scout_balcony_reference_data.dart').write_text('\n'.join(lines)+'\n')
print(f'Imported 249 seats, 21 table outlines and source group 22; SHA256 {digest}')
